# Stable bootstrap. Business builds fetch the online CLI before selecting Go.
# Generated by fuloot-dev; keep this file in each project's repository.
fuloot_use_go() {
  FULOOT_TOOLCHAIN="$1"
  printf '%s\n' "$FULOOT_TOOLCHAIN" | LC_ALL=C grep -Eq '^go1\.[0-9]+\.[0-9]+$' || {
    echo "Invalid CLI toolchain: $FULOOT_TOOLCHAIN" >&2; return 1
  }
  export GOTOOLCHAIN="$FULOOT_TOOLCHAIN" GOWORK=off
  FULOOT_ACTUAL_GO=$("$GO_CMD" env GOVERSION) || return 1
  [ "$FULOOT_ACTUAL_GO" = "$FULOOT_TOOLCHAIN" ] || {
    echo "Expected $FULOOT_TOOLCHAIN, got $FULOOT_ACTUAL_GO" >&2; return 1
  }
}

fuloot_fetch_cli() {
  git -C "$FULOOT_FETCH_DIR" init --quiet || return 1
  git -C "$FULOOT_FETCH_DIR" fetch --quiet --depth=1 -- "$FULOOT_CLI_REPOSITORY" "$FULOOT_CLI_REF" || return 1
  git -C "$FULOOT_FETCH_DIR" checkout --quiet --detach FETCH_HEAD || return 1
  FULOOT_CLI_COMMIT=$(git -C "$FULOOT_FETCH_DIR" rev-parse HEAD) || return 1
  [ -f "$FULOOT_FETCH_DIR/scripts/fuloot-build.sh" ] && [ -f "$FULOOT_FETCH_DIR/.fuloot-toolchain" ] || {
    echo "Online CLI $FULOOT_CLI_COMMIT does not provide the build bootstrap; publish the CLI changes first." >&2
    return 1
  }
  echo "==> Online CLI $FULOOT_CLI_REF -> $FULOOT_CLI_COMMIT"
  # The hook and CLI dependency come from this same immutable revision.
  . "$FULOOT_FETCH_DIR/scripts/fuloot-build.sh" || return 1
  fuloot_remote_setup "$1" "$FULOOT_FETCH_DIR" || return 1
}

fuloot_go_setup() {
  if [ -n "${GO_BINARY:-}" ]; then
    GO_CMD="$GO_BINARY"
  elif command -v go >/dev/null 2>&1; then
    GO_CMD=$(command -v go)
  elif [ -x /usr/local/go/bin/go ]; then
    GO_CMD=/usr/local/go/bin/go
  else
    echo "Go not found; install Go or set GO_BINARY" >&2; return 1
  fi
  export GO_BINARY="$GO_CMD"
  case "${FULOOT_CLI_SYNC:-1}" in
    0|1) ;;
    *) echo "FULOOT_CLI_SYNC must be 0 or 1" >&2; return 1 ;;
  esac
  # The CLI must be buildable before its changes are published. Explicit frozen
  # builds also use checked-in pins without contacting GitHub.
  if grep -Eq '^module github.com/laputacn/fuloot-cli[[:space:]]*$' "$1/go.mod" || [ "${FULOOT_CLI_SYNC:-1}" = 0 ]; then
    FULOOT_TOOLCHAIN=$(cat "$1/.fuloot-toolchain") || return 1
    case "${GOTOOLCHAIN:-}" in
      ""|auto|"$FULOOT_TOOLCHAIN") ;;
      *) echo "GOTOOLCHAIN=$GOTOOLCHAIN conflicts with project policy $FULOOT_TOOLCHAIN" >&2; return 1 ;;
    esac
    echo "==> Local pinned build ($FULOOT_TOOLCHAIN)"
    fuloot_use_go "$FULOOT_TOOLCHAIN" || return 1
    return 0
  fi
  FULOOT_CLI_REPOSITORY="${FULOOT_CLI_REPOSITORY:-https://github.com/laputacn/fuloot-cli.git}"
  FULOOT_CLI_REF="${FULOOT_CLI_REF:-main}"
  FULOOT_FETCH_DIR=$(mktemp -d "${TMPDIR:-/tmp}/fuloot-cli.XXXXXXXX") || return 1
  if fuloot_fetch_cli "$1"; then
    rm -rf -- "$FULOOT_FETCH_DIR"
  else
    rm -rf -- "$FULOOT_FETCH_DIR"
    echo "CLI synchronization failed; build stopped (no stale CLI fallback)." >&2
    return 1
  fi
}

fuloot_verify_go() {
  FULOOT_BINARY_GO=$("$GO_CMD" version -m "$1" | sed -n '1s/.*: //p') || return 1
  [ "$FULOOT_BINARY_GO" = "$FULOOT_TOOLCHAIN" ] || {
    echo "Artifact $1 uses $FULOOT_BINARY_GO, expected $FULOOT_TOOLCHAIN" >&2; return 1
  }
  if [ -n "${FULOOT_CLI_VERSION:-}" ]; then
    FULOOT_BINARY_CLI=$("$GO_CMD" version -m "$1" | awk '$1 == "dep" && $2 == "github.com/laputacn/fuloot-cli" {print $3}') || return 1
    # Some plugin binaries only use runtime libraries and do not link the CLI.
    [ -z "$FULOOT_BINARY_CLI" ] || [ "$FULOOT_BINARY_CLI" = "$FULOOT_CLI_VERSION" ] || {
      echo "Artifact $1 uses CLI $FULOOT_BINARY_CLI, expected $FULOOT_CLI_VERSION" >&2; return 1
    }
  fi
}
